package com.sih.hr.service;
import static org.junit.jupiter.api.Assertions.*; import com.sih.hr.dto.HrDtos.*; import com.sih.shared.tenant.TenantContext; import java.time.*; import java.util.UUID; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.web.server.ResponseStatusException;
@SpringBootTest class HrWorkflowServiceIT { @Autowired HrWorkflowService service; @AfterEach void clear(){TenantContext.clear();} private CreateStaffRequest staff(){return new CreateStaffRequest("EMP-"+UUID.randomUUID(),"Marie","Ndiaye","Urgences","Infirmière",true,"marie@example.test",LocalDate.now());} @Test void blocksClinicalShiftForExpiredCredentialThenAllowsRenewal(){TenantContext.setCurrentTenant("hospital-a");var person=service.createStaff(staff());var credential=service.createCredential(new CreateCredentialRequest(person.id(),"LICENSE","LIC-1",LocalDate.now().minusYears(2),LocalDate.now().minusDays(1)));var shift=new CreateShiftRequest(person.id(),"Urgences","NUIT",OffsetDateTime.now().plusDays(2),OffsetDateTime.now().plusDays(2).plusHours(12),null);assertThrows(ResponseStatusException.class,()->service.createShift(shift));service.renewCredential(credential.id(),new RenewCredentialRequest(LocalDate.now().plusYears(1)));assertEquals("DRAFT",service.createShift(shift).status());} @Test void isolatesStaffAcrossTenants(){TenantContext.setCurrentTenant("hospital-a");var person=service.createStaff(staff());TenantContext.setCurrentTenant("hospital-b");assertTrue(service.listStaff().isEmpty());assertThrows(ResponseStatusException.class,()->service.createShift(new CreateShiftRequest(person.id(),"Bloc","JOUR",OffsetDateTime.now().plusDays(1),OffsetDateTime.now().plusDays(1).plusHours(8),null)));} }
